package com.vit.archds.service;
import com.vit.archds.dto.AuthDtos.*; import com.vit.archds.entity.*; import com.vit.archds.repository.*; import com.vit.archds.security.JwtService; import org.springframework.security.authentication.*; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class AuthService { private final UserRepository users; private final PasswordEncoder encoder; private final AuthenticationManager auth; private final JwtService jwt; private final AuditLogRepository audit; public AuthService(UserRepository u,PasswordEncoder e,AuthenticationManager a,JwtService j,AuditLogRepository l){users=u;encoder=e;auth=a;jwt=j;audit=l;}
 @Transactional public AuthResponse register(Register r){String e=r.email().toLowerCase();if(users.existsByEmail(e))throw new IllegalArgumentException("Email is already registered");User u=users.save(new User(r.name().trim(),e,encoder.encode(r.password()),Role.USER));audit.save(new AuditLog(u,"REGISTER","USER",null));return new AuthResponse(jwt.generate(u),u.getId(),u.getName(),u.getEmail(),u.getRole().name());}
 @Transactional public AuthResponse login(Login r){auth.authenticate(new UsernamePasswordAuthenticationToken(r.email().toLowerCase(),r.password()));User u=users.findByEmail(r.email().toLowerCase()).orElseThrow();audit.save(new AuditLog(u,"LOGIN","USER",null));return new AuthResponse(jwt.generate(u),u.getId(),u.getName(),u.getEmail(),u.getRole().name());}}
